											{
												customer_count = Customer_Register.count();
												next_no = customer_count + 1;
												if(next_no < 10)
												{
													num_text = "00" + next_no;
												}
												else if(next_no < 100)
												{
													num_text = "0" + next_no;
												}
												else
												{
													num_text = next_no.toString();
												}
												input.Customer_Code = "CP" + num_text;
											}
										}
										// =====================================================
										// CREDIT CUSTOMER
										// =====================================================
										if(input.Customer_Type == "Credit")
