										duplicate_customer_found = false;
										duplicate_customer_name = "";
										current_customer_name = ifnull(input.Customer_Name,"").trim().toLowerCase();
										for each  customer_rec in Customer_Register[ID != 0]
										{
											check_record = true;
											if(input.ID != null && customer_rec.ID == input.ID)
											{
												check_record = false;
											}
											if(check_record == true)
											{
												existing_name = ifnull(customer_rec.Customer_Name,"").trim().toLowerCase();
												if(current_customer_name != "" && existing_name == current_customer_name)
												{
													duplicate_customer_found = true;
													duplicate_customer_name = ifnull(customer_rec.Display_Name_Customer,customer_rec.Customer_Name);
													break;
												}
												if(input.Customer_Type == "Credit" && input.Customer != null)
												{
													if(customer_rec.Customer != null && customer_rec.Customer.ID == input.Customer.ID)
													{
														duplicate_customer_found = true;
														duplicate_customer_name = ifnull(customer_rec.Display_Name_Customer,customer_rec.Customer_Name);
														break;
													}
												}
											}
										}
										if(duplicate_customer_found == true)
