											if(oldRec.ID != null && oldRec.Voucher_Status == "Returned" && input.Voucher_Status != "Returned")
											{
												for each  bundle in input.Stock_Bundling_Note
												{
													if(bundle.Item == null)
													{
														errors = errors + "\n• Stock Bundling Note has a row without Item.";
														continue;
													}
													qty_created = ifnull(bundle.Quantity_Created,0.0);
													if(qty_created <= 0)
													{
														errors = errors + "\n• Quantity Created is required for " + ifnull(bundle.Display_Name_Item,"") + ".";
														continue;
													}
													formula = Product_Formula_Register[Item == bundle.Item && Status == "Active"];
													if(formula.ID == null)
													{
														errors = errors + "\n• No active Product Formula found for " + ifnull(bundle.Display_Name_Item,"") + ".";
														continue;
													}
													for each  fm in Product_Formula_Details[Product == formula.ID]
													{
														required_qty = ifnull(fm.Quantity_in_Base_Unit_Of_Measure,0.0) * qty_created;
														issued_qty = 0.0;
														for each  issue in Item_Issuing_Details[Issuing_Voucher == input.ID]
														{
															if(issue.Item != null && issue.Item == fm.Material)
															{
																issued_qty = issued_qty + ifnull(issue.Quantity_in_Base_Unit_Of_Measure,0.0);
															}
														}
														if(issued_qty > required_qty)
														{
															if(input.Allow_Excess_Material_Issued != true)
															{
																errors = errors + "\n• Too much material issued for " + ifnull(fm.Display_Name_Material,"") + ". Required by formula: " + required_qty + ", Issued: " + issued_qty + ". Tick Allow Excess Material Issued Against Product Formula to continue.";
															}
															else
															{
																reason_txt = ifnull(input.Reason_Why_Material_Issued_Exceeded_Formula,"").trim();
																if(reason_txt == "")
																{
																	errors = errors + "\n• Reason Why Excess Material Was Issued Against Product Formula is required.";
																}
																else if(reason_txt.length() < 30)
																{
																	errors = errors + "\n• Reason Why Excess Material Was Issued Against Product Formula must be at least 30 characters.";
																}
															}
														}
													}
												}
											}
										}
